namespace sv_3351ea8f1f3440b594bb644aaf471041.Services;

public record TaskItem(int Id, string Title, string Assignee, string Priority, DateTime DueDate, string Status);

public interface ITaskService
{
    Task<List<TaskItem>> GetAllTasksAsync();
    Task<TaskItem> CreateTaskAsync(string title, string assignee, string priority, DateTime dueDate);
    Task UpdateTaskStatusAsync(int taskId, string newStatus);
}

@page "/board"
@using sv_3351ea8f1f3440b594bb644aaf471041.Services
@inject ITaskService TaskService
@rendermode InteractiveServer

<PageTitle>Kanban Board</PageTitle>

<h2 class="mb-3">Project Board</h2>

@if (_loading)
{
    <div class="d-flex justify-content-center my-5">
        <div class="spinner-border" role="status">
            <span class="visually-hidden">Loading…</span>
        </div>
    </div>
}
else if (_error is not null)
{
    <div class="alert alert-danger" role="alert">
        <strong>Error:</strong> @_error
        <button class="btn btn-sm btn-outline-danger ms-3" @onclick="LoadTasksAsync">Retry</button>
    </div>
}
else
{
    <!-- Stats bar -->
    <div class="row g-2 mb-3">
        <div class="col"><div class="card text-center p-2"><small class="text-muted">Total</small><strong>@_allTasks.Count</strong></div></div>
        <div class="col"><div class="card text-center p-2"><small class="text-muted">To Do</small><strong>@TasksInColumn("To Do").Count</strong></div></div>
        <div class="col"><div class="card text-center p-2"><small class="text-muted">In Progress</small><strong>@TasksInColumn("In Progress").Count</strong></div></div>
        <div class="col"><div class="card text-center p-2"><small class="text-muted">Done</small><strong>@TasksInColumn("Done").Count</strong></div></div>
        <div class="col"><div class="card text-center p-2"><small class="text-muted">Overdue</small><strong class="text-danger">@OverdueCount</strong></div></div>
    </div>

    <!-- Search bar -->
    <div class="mb-3">
        <input type="text" class="form-control" placeholder="Search tasks by title…"
               @bind="_searchTerm" @bind:event="oninput" />
    </div>

    <!-- Kanban columns -->
    <div class="row g-3">
        @for (var i = 0; i < Columns.Length; i++)
        {
            var colIndex = i;
            var colName = Columns[colIndex];
            var tasks = FilteredTasksInColumn(colName);

            <div class="col-md-4">
                <div class="card h-100">
                    <div class="card-header d-flex justify-content-between align-items-center">
                        <strong>@colName</strong>
                        <span class="badge bg-secondary">@tasks.Count</span>
                    </div>
                    <div class="card-body d-flex flex-column gap-2 overflow-auto" style="max-height:65vh;">
                        @foreach (var task in tasks)
                        {
                            <div class="card shadow-sm">
                                <div class="card-body p-2">
                                    <h6 class="card-title mb-1">@task.Title</h6>
                                    <p class="mb-1 small text-muted">@task.Assignee</p>
                                    <div class="d-flex justify-content-between align-items-center mb-1">
                                        <span class="badge @PriorityClass(task.Priority)">@task.Priority</span>
                                        <small class="text-muted">@task.DueDate.ToString("MMM dd")</small>
                                    </div>
                                    <div class="d-flex gap-1">
                                        @if (colIndex > 0)
                                        {
                                            <button class="btn btn-outline-secondary btn-sm flex-fill"
                                                    disabled="@_operationInProgress"
                                                    @onclick="() => MoveTaskAsync(task.Id, Columns[colIndex - 1])">
                                                ← Move Left
                                            </button>
                                        }
                                        @if (colIndex < Columns.Length - 1)
                                        {
                                            <button class="btn btn-outline-secondary btn-sm flex-fill"
                                                    disabled="@_operationInProgress"
                                                    @onclick="() => MoveTaskAsync(task.Id, Columns[colIndex + 1])">
                                                Move Right →
                                            </button>
                                        }
                                    </div>
                                </div>
                            </div>
                        }

                        @if (_showForm == colName)
                        {
                            <div class="card border-primary">
                                <div class="card-body p-2">
                                    <input type="text" class="form-control form-control-sm mb-1"
                                           placeholder="Title" @bind="_newTitle" />
                                    <input type="text" class="form-control form-control-sm mb-1"
                                           placeholder="Assignee" @bind="_newAssignee" />
                                    <select class="form-select form-select-sm mb-1" @bind="_newPriority">
                                        <option value="High">High</option>
                                        <option value="Medium">Medium</option>
                                        <option value="Low">Low</option>
                                    </select>
                                    <input type="date" class="form-control form-control-sm mb-2"
                                           @bind="_newDueDate" />
                                    <div class="d-flex gap-1">
                                        <button class="btn btn-primary btn-sm flex-fill"
                                                disabled="@_operationInProgress"
                                                @onclick="() => SaveTaskAsync(colName)">
                                            Save
                                        </button>
                                        <button class="btn btn-outline-secondary btn-sm flex-fill"
                                                @onclick="CancelForm">
                                            Cancel
                                        </button>
                                    </div>
                                </div>
                            </div>
                        }
                    </div>
                    <div class="card-footer">
                        <button class="btn btn-outline-primary btn-sm w-100"
                                @onclick="() => ShowAddForm(colName)">
                            + Add Task
                        </button>
                    </div>
                </div>
            </div>
        }
    </div>
}

@code {
    private static readonly string[] Columns = ["To Do", "In Progress", "Done"];

    private List<TaskItem> _allTasks = [];
    private bool _loading = true;
    private string? _error;
    private string _searchTerm = string.Empty;
    private bool _operationInProgress;

    // Add-task form state
    private string? _showForm;
    private string _newTitle = string.Empty;
    private string _newAssignee = string.Empty;
    private string _newPriority = "Medium";
    private DateTime _newDueDate = DateTime.Today.AddDays(7);

    protected override async Task OnInitializedAsync()
    {
        await LoadTasksAsync();
    }

    private async Task LoadTasksAsync()
    {
        _loading = true;
        _error = null;
        try
        {
            _allTasks = await TaskService.GetAllTasksAsync();
        }
        catch (Exception ex)
        {
            _error = ex.Message;
        }
        finally
        {
            _loading = false;
        }
    }

    private List<TaskItem> TasksInColumn(string status) =>
        _allTasks.Where(t => t.Status == status).ToList();

    private List<TaskItem> FilteredTasksInColumn(string status) =>
        _allTasks
            .Where(t => t.Status == status &&
                        (string.IsNullOrWhiteSpace(_searchTerm) ||
                         t.Title.Contains(_searchTerm, StringComparison.OrdinalIgnoreCase)))
            .ToList();

    private int OverdueCount =>
        _allTasks.Count(t => t.DueDate.Date < DateTime.Today && t.Status != "Done");

    private static string PriorityClass(string priority) => priority switch
    {
        "High" => "bg-danger",
        "Medium" => "bg-warning text-dark",
        "Low" => "bg-success",
        _ => "bg-secondary"
    };

    private async Task MoveTaskAsync(int taskId, string newStatus)
    {
        _operationInProgress = true;
        try
        {
            await TaskService.UpdateTaskStatusAsync(taskId, newStatus);
            var idx = _allTasks.FindIndex(t => t.Id == taskId);
            if (idx >= 0)
                _allTasks[idx] = _allTasks[idx] with { Status = newStatus };
        }
        catch (Exception ex)
        {
            _error = ex.Message;
        }
        finally
        {
            _operationInProgress = false;
        }
    }

    private void ShowAddForm(string column)
    {
        _showForm = column;
        _newTitle = string.Empty;
        _newAssignee = string.Empty;
        _newPriority = "Medium";
        _newDueDate = DateTime.Today.AddDays(7);
    }

    private void CancelForm() => _showForm = null;

    private async Task SaveTaskAsync(string column)
    {
        if (string.IsNullOrWhiteSpace(_newTitle))
            return;

        _operationInProgress = true;
        try
        {
            var created = await TaskService.CreateTaskAsync(_newTitle.Trim(), _newAssignee.Trim(), _newPriority, _newDueDate);
            // The service creates tasks; if the column isn't "To Do", move it immediately
            if (column != "To Do")
                await TaskService.UpdateTaskStatusAsync(created.Id, column);

            _allTasks.Add(created with { Status = column });
            _showForm = null;
        }
        catch (Exception ex)
        {
            _error = ex.Message;
        }
        finally
        {
            _operationInProgress = false;
        }
    }
}

